import * as THREE from 'three';

export const WAVE = {
  crestZ: -4.8,
  crestDrift: 1.15,
  crestWidth: 6.2,
  crestHeight: 2.4,
  boardZ: 0.8
};

/** Shared CPU implementation of the ocean surface. */
export function waveHeight(x, z, t) {
  const zc = WAVE.crestZ + WAVE.crestDrift * Math.sin(t * 0.13);
  const d = (z - zc) / WAVE.crestWidth;
  const ridge = Math.exp(-d * d);

  let h = WAVE.crestHeight * ridge;
  h += 0.38 * ridge * Math.sin(x * 0.22 + z * 0.15 - t * 0.6);
  h += 0.12 * Math.sin(x * 0.52 + t * 1.15);
  h += 0.08 * Math.sin(z * 0.8 - t * 1.5 + x * 0.18);
  h += 0.06 * Math.sin((x + z) * 1.15 + t * 1.9);
  h +=
    0.5 *
    Math.exp(-Math.pow((z + 14) / 8, 2)) *
    (0.8 + 0.2 * Math.sin(x * 0.12 + t * 0.2));

  return h;
}

export function waveNormal(x, z, t, target = new THREE.Vector3()) {
  const e = 0.14;
  const hl = waveHeight(x - e, z, t);
  const hr = waveHeight(x + e, z, t);
  const hd = waveHeight(x, z - e, t);
  const hu = waveHeight(x, z + e, t);
  return target.set(hl - hr, 2 * e, hd - hu).normalize();
}

/** GLSL mirror of the functions above. */
export const waveGLSL = /* glsl */ `
  float waveHeight(vec2 p, float t) {
    float zc = -4.8 + 1.15 * sin(t * 0.13);
    float d = (p.y - zc) / 6.2;
    float ridge = exp(-d * d);

    float h = 2.4 * ridge;
    h += 0.38 * ridge * sin(p.x * 0.22 + p.y * 0.15 - t * 0.6);
    h += 0.12 * sin(p.x * 0.52 + t * 1.15);
    h += 0.08 * sin(p.y * 0.8 - t * 1.5 + p.x * 0.18);
    h += 0.06 * sin((p.x + p.y) * 1.15 + t * 1.9);
    h += 0.5 * exp(-pow((p.y + 14.0) / 8.0, 2.0)) * (0.8 + 0.2 * sin(p.x * 0.12 + t * 0.2));
    return h;
  }

  vec3 waveNormal(vec2 p, float t) {
    float e = 0.14;
    float hl = waveHeight(p - vec2(e, 0.0), t);
    float hr = waveHeight(p + vec2(e, 0.0), t);
    float hd = waveHeight(p - vec2(0.0, e), t);
    float hu = waveHeight(p + vec2(0.0, e), t);
    return normalize(vec3(hl - hr, 2.0 * e, hd - hu));
  }
`;
