import * as THREE from 'three';
import { makeCloudTexture, makeGlowTexture, mulberry32 } from './utils.js';
import { waveHeight } from './waves.js';

export const SUN_DIR = new THREE.Vector3(0.27, 0.075, -0.96).normalize();

export function createSky(scene) {
  const group = new THREE.Group();
  scene.add(group);

  /* ------------------------------- sky dome ------------------------------- */
  const skyUniforms = {
    uZenith: { value: new THREE.Color(0x27224f) },
    uUpper: { value: new THREE.Color(0x754063) },
    uMid: { value: new THREE.Color(0xdc6d6c) },
    uHorizon: { value: new THREE.Color(0xffc58b) },
    uSunColor: { value: new THREE.Color(0xffd7a0) },
    uSunDir: { value: SUN_DIR.clone() }
  };

  const skyMaterial = new THREE.ShaderMaterial({
    uniforms: skyUniforms,
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uZenith;
      uniform vec3 uUpper;
      uniform vec3 uMid;
      uniform vec3 uHorizon;
      uniform vec3 uSunColor;
      uniform vec3 uSunDir;
      varying vec3 vDir;

      void main() {
        vec3 dir = normalize(vDir);
        float h = dir.y;

        vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.16, h));
