import * as THREE from 'three';
import { waveGLSL } from './waves.js';

export function createOcean(scene) {
  const uniforms = {
    uTime: { value: 0 },
    uDeep: { value: new THREE.Color(0x082f3d) },
    uMid: { value: new THREE.Color(0x0c5b63) },
    uShallow: { value: new THREE.Color(0x1a8583) },
    uSky: { value: new THREE.Color(0x9c5270) },
    uHorizon: { value: new THREE.Color(0xffb68b) },
    uFoam: { value: new THREE.Color(0xfff0d8) },
    uSunDir: { value: new THREE.Vector3(0.27, 0.075, -0.96).normalize() },
    uBoardPos: { value: new THREE.Vector2(0, 0.8) }
  };

  const geometry = new THREE.PlaneGeometry(220, 220, 300, 300);
  geometry.rotateX(-Math.PI / 2);

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: /* glsl */ `
      uniform float uTime;
      varying vec3 vWorldPos;
      varying vec3 vNormalW;
      varying float vHeight;

      ${waveGLSL}

      void main() {
        vec3 pos = position;
        float h = waveHeight(pos.xz, uTime);
        pos.y += h;

        vec3 n = waveNormal(pos.xz, uTime);
        vec4 world = modelMatrix * vec4(pos, 1.0);

        vWorldPos = world.xyz;
        vNormalW = normalize(mat3(modelMatrix) * n);
        vHeight = h;

        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uDeep;
      uniform vec3 uMid;
      uniform vec3 uShallow;
      uniform vec3 uSky;
      uniform vec3 uHorizon;
      uniform vec3 uFoam;
      uniform vec3 uSunDir;
      uniform vec2 uBoardPos;

      varying vec3 vWorldPos;
      varying vec3 vNormalW;
      varying float vHeight;

      float hash21(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }

      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash21(i);
        float b = hash21(i + vec2(1.0, 0.0));
        float c = hash21(i + vec2(0.0, 1.0));
        float d = hash21(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }

      float fbm(vec2 p) {
        float value = 0.0;
        float amplitude = 0.5;
        for (int i = 0; i < 4; i++) {
          value += amplitude * noise(p);
          p = p * 2.03 + vec2(13.1, 7.7);
          amplitude *= 0.5;
        }
        return value;
      }

      void main() {
        vec3 N = normalize(vNormalW);
        vec3 V = normalize(cameraPosition - vWorldPos);
        float ndv = clamp(dot(N, V), 0.0, 1.0);
        float fresnel = pow(1.0 - ndv, 4.0);

        vec3 base = mix(uDeep, uMid, smoothstep(-0.4, 1.15, vHeight));
        base = mix(base, uShallow, smoothstep(0.8, 2.25, vHeight) * 0.55);

        vec3 reflected = reflect(-V, N);
        vec3 skyReflection = mix(uHorizon, uSky, smoothstep(-0.03, 0.38, reflected.y));
        vec3 col = mix(base, skyReflection, 0.18 + fresnel * 0.67);

        vec3 L = normalize(uSunDir);
        vec3 H = normalize(L + V);
        float ndh = max(dot(N, H), 0.0);
        float specular = pow(ndh, 260.0);
        float glitter = pow(ndh, 22.0);

        col += vec3(1.0, 0.50, 0.22) * specular * 4.2;
        col += vec3(1.0, 0.38, 0.15) * glitter * 0.22;

        float sunPath = pow(max(0.0, dot(normalize(vec3(V.x, 0.0, V.z)), normalize(vec3(uSunDir.x, 0.0, uSunDir.z)))), 10.0);
        col += vec3(1.0, 0.34, 0.13) * sunPath * 0.09 * (0.45 + fresnel);

        vec2 q = vWorldPos.xz;
        float n1 = fbm(q * 0.55 + vec2(uTime * 0.14, -uTime * 0.08));
        float n2 = fbm(q * 2.1 - vec2(uTime * 0.28, uTime * 0.05));
        float n3 = noise(q * 5.0 + vec2(uTime * 0.6, -uTime * 0.2));

        float zc = -4.8 + 1.15 * sin(uTime * 0.13);
        float crestBand = exp(-pow((vWorldPos.z - zc) / 0.72, 2.0));
        float crest = smoothstep(1.55, 2.2, vHeight + (n1 - 0.5) * 0.65);
        float caps = smoothstep(0.43, 0.72, n1 * 0.8 + n2 * 0.35) * smoothstep(1.05, 1.8, vHeight);
        float foam = clamp(crest * (0.55 + n2 * 0.9) + caps * 0.5 + crestBand * smoothstep(0.4, 0.78, n2) * 0.32, 0.0, 1.0);
        foam *= 0.75 + n3 * 0.25;

        float dx = vWorldPos.x - uBoardPos.x;
        float dz = vWorldPos.z - uBoardPos.y;
        float contact = smoothstep(1.35, 0.22, length(vec2(dx * 0.82, dz * 1.55)));
        float wake = exp(-pow(dz / 0.7, 2.0)) * exp(-max(dx, 0.0) * 0.28) * smoothstep(-0.45, 0.7, dx);
        float wakeFoam = contact * 0.6 + wake * 0.38;
        wakeFoam *= 0.55 + n2 * 0.7;

        col = mix(col, uFoam, clamp(foam * 0.84 + wakeFoam, 0.0, 0.9));
        col += uFoam * contact * 0.08;

        float distanceToCamera = length(cameraPosition.xz - vWorldPos.xz);
        float haze = smoothstep(52.0, 112.0, distanceToCamera);
        col = mix(col, uHorizon, haze);

        // A hint of sparkle in the foam so it feels like wet, moving light.
        col += vec3(1.0, 0.75, 0.48) * pow(n3, 7.0) * foam * 0.16;

        gl_FragColor = vec4(col, 1.0);
      }
    `
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  scene.add(mesh);

  function update(t, boardPosition) {
    uniforms.uTime.value = t;
    uniforms.uBoardPos.value.set(boardPosition.x, boardPosition.z);
  }

  return { mesh, material, uniforms, update };
}
