    })
  );
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0.1, deckY + 0.008, 0);
  group.add(contactShadow);

  return {
    group,
    board,
    deckY,
    materials: { boardMaterial, creamMaterial, tealMaterial }
  };
}
