import * as THREE from 'three';
import { waveHeight } from './waves.js';

export function createWake(scene, boardGroup) {
  const sections = 34;
  const positions = new Float32Array((sections + 1) * 2 * 3);
  const uvs = new Float32Array((sections + 1) * 2 * 2);
  const indices = [];

  for (let i = 0; i <= sections; i++) {
    const v = i / sections;
    uvs[i * 4] = 0;
    uvs[i * 4 + 1] = v;
    uvs[i * 4 + 2] = 1;
    uvs[i * 4 + 3] = v;
    if (i < sections) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geometry.setIndex(indices);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uFoam: { value: new THREE.Color(0xfff0dc) }
    },
    vertexShader: /* glsl */ `
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform float uTime;
      uniform vec3 uFoam;
      varying vec2 vUv;

      float hash21(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }

      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash21(i);
        float b = hash21(i + vec2(1.0, 0.0));
        float c = hash21(i + vec2(0.0, 1.0));
        float d = hash21(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }

      float fbm(vec2 p) {
        float value = 0.0;
        float amplitude = 0.5;
        for (int i = 0; i < 3; i++) {
          value += amplitude * noise(p);
          p = p * 2.06 + vec2(7.3, 2.1);
          amplitude *= 0.5;
        }
        return value;
      }

      void main() {
        float edge = smoothstep(0.0, 0.26, vUv.x) * smoothstep(1.0, 0.74, vUv.x);
        float lengthFade = smoothstep(1.0, 0.0, vUv.y);
        float n = fbm(vec2(vUv.x * 9.0 + 4.0, vUv.y * 30.0 - uTime * 1.25));
        float n2 = noise(vec2(vUv.x * 26.0 + 3.0, vUv.y * 64.0 - uTime * 2.1));
        float lace = smoothstep(0.35, 0.72, n * 0.68 + n2 * 0.32);
        float alpha = edge * locale_never_used();
        alpha = edge * lace * (0.16 + 0.84 * lengthFade) * 0.62;
        if (alpha < 0.005) discard;
        vec3 color = mix(uFoam, vec3(1.0, 0.78, 0.62), vUv.y * 0.5);
        gl_FragColor = vec4(color, alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = 3;
  scene.add(mesh);

  const local = new THREE.Vector3();
  const world = new THREE.Vector3();
  const nextWorld = new THREE.Vector3();
  const tangent = new THREE.Vector3();
  const side = new THREE.Vector3();
  const centerline = [];

  for (let i = 0; i <= sections; i++) centerline.push(new THREE.Vector3());

  function update(t) {
    material.uniforms.uTime.value = t;
    boardGroup.localToWorld(world.set(1.15, 0.02, 0));
    const startX = world.x;
    const startZ = world.z;

    for (let i = 0; i <= sections; i++) {
      const s = i / sections;
      const localDistance = 1.15 + s * 7.4;
      boardGroup.localToWorld(local.set(localDistance, 0.02, 0));
      const x = local.x;
      const z = local.z;
      const y = waveHeight(x, z, t) + 0.032;
      centerline[i].set(x, y, z);
    }

    for (let i = 0; i <= sections; i++) {
      const s = i / sections;
      const p = centerline[i];
      const prev = centerline[Math.max(0, i - 1)];
      const next = centerline[Math.min(sections, i + 1)];
      tangent.subVectors(next, prev);
      tangent.y = 0;
      if (tangent.lengthSq() < 1e-6) tangent.set(1, 0, 0);
      tangent.normalize();
      side.set(-tangent.z, 0, tangent.x);

      const width = 0.28 + s * 2.35 + Math.sin(s * 16.0 + t * 1.5) * 0.16 * s;
      const a = i * 6;
      positions[a] = p.x + side.x * width * 0.5;
      positions[a + 1] = p.y;
      positions[a + 2] = p.z + side.z * width * 0.5;
      positions[a + 3] = p.x - side.x * width * 0.5;
      positions[a + 4] = p.y;
      positions[a + 5] = p.z - side.z * width * 0.5;
    }

    geometry.attributes.position.needsUpdate = true;
  }

  return { mesh, update };
}
